function s(){try{const t=localStorage.getItem("kiini_system_settings");if(t)return JSON.parse(t).dateFormat||null}catch{}return null}function l(t,e){const n=t.getDate(),g=String(n).padStart(2,"0"),a=t.getMonth()+1,o=String(a).padStart(2,"0"),r=t.getFullYear(),c=t.toLocaleDateString("en-US",{month:"short"}),i=t.toLocaleDateString("en-US",{month:"long"});return e.replace(/dd/g,g).replace(/\bd\b/g,String(n)).replace(/MMMM/g,i).replace(/MMM/g,c).replace(/MM/g,o).replace(/\bM\b/g,c).replace(/yyyy/g,String(r)).replace(/\bY\b/g,String(r)).replace(/\by\b/g,String(r).slice(-2)).replace(/\bm\b/g,o).replace(/\bj\b/g,String(n)).replace(/\bF\b/g,i).replace(/\bn\b/g,String(a))}function u(t){try{const e=new Date(t),n=s();return n?l(e,n):e.toLocaleDateString("en-US",{year:"numeric",month:"short",day:"numeric"})}catch{return"Invalid date"}}function m(t){try{const e=new Date(t),n={year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"};return e.toLocaleDateString("en-US",n)}catch{return"Invalid date"}}function S(t,e="KES"){try{return e==="KES"?`Ksh ${t.toLocaleString("en-KE",{minimumFractionDigits:0,maximumFractionDigits:2})}`:new Intl.NumberFormat("en-US",{style:"currency",currency:e}).format(t)}catch{return`Ksh ${t.toFixed(2)}`}}function h(t,e=1){return`${(t*100).toFixed(e)}%`}export{u as a,S as b,h as c,m as f};
